/**
 * Sketch branches — ephemeral exploration spaces for trying N variants of
 * an entity (or a single field) without polluting the main chat.
 *
 * Storage shape:
 *   projects/<slug>/99-ai/branches/<id>.json
 *
 * Lifecycle:
 *   create  → status='open'   (generated by AI, persisted as JSON)
 *   apply   → status='merged' (one variant becomes the entity's new state)
 *   discard → status='discarded' OR deleted from disk
 *
 * NOTE: branches are persisted (so they survive a tab reload) but they
 * always live OUTSIDE the entity files themselves — the entity is only
 * mutated when the user picks "Aplicar".
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';

const BRANCHES_DIR = path.join('99-ai', 'branches');

export type SketchScope = {
  /** Entity reference like "personaje/mara". */
  entityRef: string;
  /** When set, the branch varies only this single field (e.g. "Want"). When
   *  null, each variant is a full body replacement. */
  fieldKey: string | null;
};

export type SketchVariant = {
  id: string;              // 'a' | 'b' | 'c' | …
  label: string;           // short title from the model
  /** When the branch is field-scoped, the proposed new value of that field. */
  value?: string;
  /** When the branch is full-entity, the proposed full body markdown. */
  body?: string;
  /** Raw chunk for debugging — the full <<<VARIANT…<<<END>>> block. */
  raw: string;
};

export type SketchBranch = {
  id: string;
  scope: SketchScope;
  prompt: string;
  variants: SketchVariant[];
  status: 'open' | 'merged' | 'discarded';
  created: string;
  /** When merged, which variant was applied and when. */
  applied?: { variantId: string; ts: string };
};

const ID_RE = /^[a-z0-9][a-z0-9-]*$/;

function branchesRoot(projectRoot: string): string {
  return path.join(projectRoot, BRANCHES_DIR);
}

function branchFile(projectRoot: string, id: string): string {
  if (!ID_RE.test(id)) throw new Error(`invalid branch id: ${id}`);
  return path.join(branchesRoot(projectRoot), `${id}.json`);
}

/** Generate a short, sortable id like '20260517-093412-aux'. */
export function newBranchId(): string {
  const ts = new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
  const rand = Math.random().toString(36).slice(2, 6);
  return `${ts}-${rand}`;
}

export async function saveBranch(projectRoot: string, branch: SketchBranch): Promise<void> {
  const file = branchFile(projectRoot, branch.id);
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, JSON.stringify(branch, null, 2), 'utf-8');
}

export async function readBranch(projectRoot: string, id: string): Promise<SketchBranch | null> {
  try {
    const raw = await fs.readFile(branchFile(projectRoot, id), 'utf-8');
    return JSON.parse(raw) as SketchBranch;
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
    throw err;
  }
}

export async function deleteBranch(projectRoot: string, id: string): Promise<void> {
  try {
    await fs.rm(branchFile(projectRoot, id), { force: true });
  } catch {/* ignore */}
}

/**
 * Parse `<<<VARIANT:id:label>>>…<<<END>>>` blocks from an assistant turn.
 * The id is normalized to a short kebab-safe id (a/b/c are typical); the
 * label is free text up to ~60 chars; the body is the raw text between the
 * markers, trimmed. Used by POST /branches to extract the variants from a
 * single-shot AI call.
 *
 * Returns variants without `value` vs `body` decided — that's the caller's
 * job based on the branch scope (field-scoped → put text in .value).
 */
const VARIANT_RE = /<<<\s*VARIANT\s*:\s*([^:<>\n]+?)\s*:\s*([^<>\n]+?)\s*>>>([\s\S]*?)<<<\s*END\s*>>>/g;

function normalizeVariantId(raw: string): string {
  const cleaned = raw
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return cleaned || 'x';
}

export function parseVariants(text: string): Array<{ id: string; label: string; content: string; raw: string }> {
  const seen = new Set<string>();
  const out: Array<{ id: string; label: string; content: string; raw: string }> = [];
  for (const m of text.matchAll(VARIANT_RE)) {
    let id = normalizeVariantId(m[1]);
    // Dedup ids — second 'a' becomes 'a-2' etc, so the UI keys stay stable.
    if (seen.has(id)) {
      let n = 2;
      while (seen.has(`${id}-${n}`)) n++;
      id = `${id}-${n}`;
    }
    seen.add(id);
    out.push({
      id,
      label: m[2].trim().slice(0, 60),
      content: m[3].trim(),
      raw: m[0],
    });
  }
  return out;
}

/** List all branches (open + merged + discarded), newest first. */
export async function listBranches(projectRoot: string): Promise<SketchBranch[]> {
  let files: string[];
  try {
    files = await fs.readdir(branchesRoot(projectRoot));
  } catch {
    return [];
  }
  const out: SketchBranch[] = [];
  for (const f of files) {
    if (!f.endsWith('.json')) continue;
    const id = f.replace(/\.json$/, '');
    const b = await readBranch(projectRoot, id);
    if (b) out.push(b);
  }
  return out.sort((a, b) => b.created.localeCompare(a.created));
}
